public class RequestContextHolder {
    private static final ThreadLocal<UserContext> CONTEXT = new ThreadLocal<>();

    public static void setContext(UserContext context) {
        CONTEXT.set(context);
    }

    public static UserContext getContext() {
        return CONTEXT.get();
    }

    public static void clear() {
        // CRITICAL: Must be called in a finally block to prevent thread pool leaks
        CONTEXT.remove();
    }
}

// Usage inside a Servlet Filter or Task Executor
public void doWork(Runnable task) {
    try {
        RequestContextHolder.setContext(new UserContext("user-123"));
        task.run();
    } finally {
        RequestContextHolder.clear();
    }
}
